// TTL (час життя) для різних типів даних у кеші.
// Значення в мілісекундах.
export const CACHE_TTL = {
  // Каталог (список треків з фільтрами) — 5 хвилин
  catalog: 5 * 60 * 1000,

  // Популярні треки — 5 хвилин.
  // Дані рідко змінюються, тому TTL довший =
  // менше запитів до бази даних.
  popular: 5 * 60 * 1000,

  // Нові релізи — 5 хвилин
  newReleases: 5 * 60 * 1000,

  // Discovery стрічка (головна) — 5 хвилин
  discovery: 5 * 60 * 1000,

  // Окремий трек — 1 година
  track: 60 * 60 * 1000,
} as const;
